ALTER TABLE "HaHClinicalMessage" ADD COLUMN "priority" TEXT NOT NULL DEFAULT 'ROUTINE', ADD COLUMN "attachmentUrls" JSONB;
CREATE TABLE "HaHClinicalProtocolApproval" ("id" TEXT PRIMARY KEY,"protocolId" TEXT NOT NULL,"approverId" TEXT NOT NULL,"decision" TEXT NOT NULL,"note" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "HaHClinicalProtocolApproval_protocolId_fkey" FOREIGN KEY ("protocolId") REFERENCES "HaHClinicalProtocol"("id") ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT "HaHClinicalProtocolApproval_approverId_fkey" FOREIGN KEY ("approverId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE UNIQUE INDEX "HaHClinicalProtocolApproval_protocolId_approverId_key" ON "HaHClinicalProtocolApproval"("protocolId","approverId");
CREATE TABLE "HaHBreakGlassAccess" ("id" TEXT PRIMARY KEY,"episodeId" TEXT NOT NULL,"userId" TEXT NOT NULL,"reason" TEXT NOT NULL,"expiresAt" TIMESTAMP(3) NOT NULL,"revokedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "HaHBreakGlassAccess_episodeId_fkey" FOREIGN KEY ("episodeId") REFERENCES "HaHEpisode"("id") ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT "HaHBreakGlassAccess_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE INDEX "HaHBreakGlassAccess_userId_expiresAt_revokedAt_idx" ON "HaHBreakGlassAccess"("userId","expiresAt","revokedAt");
